  ('20261114210000', 'behaviour', 'evidence_bump_version also versions provenance (mime_type, file_hash)', coalesce((select bool_or(pg_get_functiondef(p.oid) like '%new.mime_type, new.file_hash%') from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'evidence_bump_version'), false)),
  ('20261114210000', 'behaviour', 'evidence_stale_on_indexed fires in both directions', coalesce((select bool_or(pg_get_triggerdef(oid) like '%old.index_status = ''indexed''%OR%new.index_status = ''indexed''%') from pg_trigger where tgname = 'evidence_stale_on_indexed'), false)),
  ('20261114210000', 'privilege', 'authenticated cannot write evidence_drafts directly', coalesce(to_regclass('public.evidence_drafts') is not null and not has_table_privilege('authenticated', 'public.evidence_drafts', 'INSERT') and not has_table_privilege('authenticated', 'public.evidence_drafts', 'UPDATE') and not has_table_privilege('authenticated', 'public.evidence_drafts', 'DELETE'), false)),
  ('20261115120000', 'constraint', 'workers.summary length check (1..1000)', coalesce((select bool_or(pg_get_constraintdef(c.oid) like '%summary%1000%') from pg_constraint c where c.conrelid = to_regclass('public.workers') and c.contype = 'c'), false)),
  ('20261117100000', 'behaviour', 'evidence_supersede_signoffs also supersedes review requests', coalesce((select bool_or(pg_get_functiondef(p.oid) like '%review_requests%') from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'evidence_supersede_signoffs'), false))
),
recorded(version) as (
  select unnest(string_to_array(coalesce(
    case when to_regclass('supabase_migrations.schema_migrations') is not null then
      (xpath('/row/v/text()', query_to_xml('select string_agg(version, '','' order by version) as v from supabase_migrations.schema_migrations', false, true, '')))[1]::text
    end, ''), ','))
)
select e.migration,
       e.migration in (select version from recorded)                                as recorded_in_history,
       count(*) filter (where e.present)                                              as present,
       count(*)                                                                       as expected,
       coalesce(string_agg(e.kind || ' ' || e.object, '; ') filter (where not e.present), '') as missing
  from expected e
 group by e.migration
union all
select r.version, true, null, null, 'recorded in history but no matching file in supabase/migrations'
  from recorded r
 where r.version <> '' and r.version not in (select migration from expected)
 order by 1;
